// Author: MiYu. Exercise the map console against an actual Win32 console device.
#include "lua_native_console.h"
#include <stdexcept>
#include <iostream>
using namespace war3;
int main(){
    try{FreeConsole();LuaNativeConsole console;if(console.enabled() || console.read())throw std::runtime_error("Console starts enabled");console.setEnabled(true);ShowWindow(GetConsoleWindow(),SW_HIDE);LuaNativeConsole other;bool busy=false;try{other.setEnabled(true);}catch(const std::exception&){busy=true;}if(!busy)throw std::runtime_error("Concurrent console ownership accepted");auto input=CreateFileW(L"CONIN$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,0,nullptr);auto output=CreateFileW(L"CONOUT$",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,0,nullptr);if(input==INVALID_HANDLE_VALUE || output==INVALID_HANDLE_VALUE)throw std::runtime_error("Console test handles unavailable");FlushConsoleInputBuffer(input);console.write("Hello");wchar_t text[5]{};DWORD count=0;if(!ReadConsoleOutputCharacterW(output,text,5,{0,0},&count) || count!=5 || std::wstring_view(text,5)!=L"Hello")throw std::runtime_error("Console output differs");INPUT_RECORD keys[4]{};wchar_t chars[]={L'中',L'x',L'\b',L'\r'};for(unsigned i=0;i<4;++i){keys[i].EventType=KEY_EVENT;keys[i].Event.KeyEvent.bKeyDown=TRUE;keys[i].Event.KeyEvent.wRepeatCount=1;keys[i].Event.KeyEvent.uChar.UnicodeChar=chars[i];}if(!WriteConsoleInputW(input,keys,3,&count) || count!=3 || console.read())throw std::runtime_error("Console partial input differs");if(!WriteConsoleInputW(input,keys+3,1,&count) || count!=1 || console.read()!=std::optional<std::string>("中"))throw std::runtime_error("Console input differs");console.setEnabled(false);if(console.enabled() || console.read())throw std::runtime_error("Console disable differs");console.setEnabled(true);ShowWindow(GetConsoleWindow(),SW_HIDE);if(!console.enabled())throw std::runtime_error("Console reenable differs");CloseHandle(input);CloseHandle(output);std::cout<<"RESULT passed=1 failed=0\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
